"""Generator for the synthetic geometric-defect fixtures in this directory.

Each fixture is a small, deterministic solid that targets ONE named defect
from the remediation review (scratchpad review/REVIEW.md, "short-list"
numbering) exactly, rather than a sculpted/scanned model. Small FILE, large
OBJECT: every fixture is a dozen-to-a-hundred triangles but is dimensioned in
tens of millimetres so it actually clears the hollowing gates it needs to
clear.

Registered constants this file's dimensions are derived from (read live from
crates/plinth-core/src/constants/placeholders.rs; restated here only for the
reasoning comments, never as a second source of truth):
    HOLLOW_SAVE_MIN_ML   = 1.5   mL  -- savings gate (the whole gate since 2026-08-13)
    HOLLOW_BULK_MIN_MM   = 10.0  mm  -- bulk-size policy
    HOLLOW_WALL_DEFAULT_MM = 2.5 mm  -- wall target
    HOLLOW_WALL_MIN_MM   = 2.0   mm  -- hard minimum wall (never lower this)
    HOLLOW_PITCH_MM      = 0.5   mm  -- hollowing voxel pitch
    HOLLOW_EXTRA_DRAIN_POLICY.min_pocket_ml   = 0.5 mL  -- audit-rescue size floor
    HOLLOW_EXTRA_DRAIN_POLICY.max_extra_drains = 3      -- audit-rescue budget
    HOLLOW_EXTRA_DRAIN_POLICY.exit_max_mm      = 8.0 mm -- audit candidate ray length
    NEAR_WALL_SKIP (rust/geom_kernel/src/consts.rs:35) = 0.05 mm

Run with Blender 5.2.1 (Blender must run OUTSIDE any process sandbox --
it segfaults on Metal detection inside one):

    blender --background --factory-startup --python generate.py -- <fixture> <output.stl>

    <fixture> is one of: legs-uneven | cascade-pocket | thin-fin

cube.stl (fixture 1) is NOT generated by this script -- it is the owner's
supplied 20mm cube (12 triangles, 684 bytes, sitting on the plate at
Z 0..20), copied in from outside git. It is the baseline: hollowed at the
2.5mm wall target it carves a 15mm cubic cavity, 15^3 = 3375 mm^3 = 3.375 mL
saved, clearing every gate (savings, bulk, wall) with no drain-planning
wrinkle at all -- one chamber, one drain, chain runs end to end.
"""

import bpy
import sys


def box(sx, sy, sz, cx, cy, cz, name):
    """An axis-aligned box, sizes and center in mm."""
    bpy.ops.mesh.primitive_cube_add(size=2, location=(cx, cy, cz))
    o = bpy.context.object
    o.scale = (sx / 2, sy / 2, sz / 2)
    o.name = name
    bpy.ops.object.transform_apply(scale=True)
    return o


def union_onto(base, parts):
    """Boolean-union each of `parts` into `base` in turn, deleting the operand."""
    for p in parts:
        m = base.modifiers.new(name="u", type='BOOLEAN')
        m.operation = 'UNION'
        m.object = p
        bpy.context.view_layer.objects.active = base
        bpy.ops.object.modifier_apply(modifier=m.name)
        bpy.data.objects.remove(p, do_unlink=True)


def export(obj, out_path):
    bpy.ops.object.select_all(action='DESELECT')
    obj.select_set(True)
    bpy.ops.wm.stl_export(filepath=out_path, export_selected_objects=True, ascii_format=False)
    print("TRIS", len(obj.data.polygons))


# ---------------------------------------------------------------------------
# FIXTURE 2 -- legs-uneven.stl
#
# Targets short-list item 3: drain sites are searched only around each
# CHAMBER's single global low point (drains.rs's `low_lobes`, band_mm=15mm),
# but a 6-connected "chamber" can span multiple legs of very different
# length. A 40x40x20 body sits on two 12x12 legs, one reaching the plate
# (Z0..40) and one stopping partway up (Z25..40). Body+both legs are ONE
# 6-connected cavity chamber, so `low_lobes` only admits planned-drain
# candidates within 15mm of the chamber's single lowest point -- the long
# leg's cavity bottom, at HOLLOW_WALL_DEFAULT_MM (2.5mm) above Z0, i.e.
# about Z 2.5. The band therefore reaches about Z 17.5. The short leg's own
# cavity bottom sits at about 25 + 2.5 = Z 27.5 -- outside that band, so it
# gets no planned drain candidate at all.
#
# This is a SEPARATE mechanism from drilling's own downhill/level-restricted
# reachability (drilling.rs:1613-1710, "drainability_map_admitted"): even
# though the short leg's cavity IS physically connected to the body and
# hence, transitively, to the long leg's cavity, it only reaches that
# connection by rising from its own bottom (Z27.5) up to Z40 where it meets
# the body -- i.e. it hangs from ITS OWN TOP, with nothing below it but a
# dead end. Resin pools at the short leg's own bottom (Z27.5) under gravity
# and cannot rise 12.5mm on its own to escape into the body. So drilling's
# own trapped/audit-rescue pass (independently of the drains.rs band bug)
# finds the short leg's cavity undrainable via the sole planned hole.
#
# MEASURED, not assumed: run through create_shell -> plan_drains ->
# drill_planned_shell with the registered M0 constants, this exact fixture
# plans exactly the two holes short-list item 3 predicts (one Drain near the
# LONG leg's base, X-12 Z3.5; one Vent up in the body, nowhere near the
# short leg) -- confirming the planning-band gap is real -- but it does NOT
# ship with the short leg refilled solid. `prepare_audit_plan`'s own rescue
# pass finds the short leg's trapped cavity, qualifies it (well over the
# 0.5 mL HOLLOW_EXTRA_DRAIN_POLICY floor) and a valid candidate direction
# out its own thin wall, and drills it its own dedicated drain
# (audit_added_drains=1, refilled_voxels=0, drainable_voxels==cavity_voxels
# -- the whole model ships hollow, both legs). The drains.rs planning gap
# short-list item 3 names is real and this fixture proves it directly; the
# "refilled to solid" CONSEQUENCE the review infers from that gap is a
# separate claim this fixture does not currently reproduce, because the
# later audit-rescue safety net (drilling.rs's own `qualifies_audit_drain` /
# `select_exact_audit_candidate`, the same machinery short-list item 4
# discusses) evidently already covers a leg this large and this exposed. A
# fixture that reproduces an actually UNRESCUABLE trapped limb (too small,
# or with no clear line-of-sight exit within HOLLOW_EXTRA_DRAIN_POLICY's
# exit_max_mm) would still need to be built to witness that consequence.
def make_legs_uneven():
    body = box(40, 40, 20, 0, 0, 50, "body")
    leg_a = box(12, 12, 40, -12, 0, 20, "legA")     # Z 0..40, reaches the plate
    leg_b = box(12, 12, 15, 12, 0, 32.5, "legB")    # Z 25..40, stops short
    union_onto(body, [leg_a, leg_b])
    return body


# ---------------------------------------------------------------------------
# FIXTURE 3 -- cascade-pocket.stl
#
# Targets short-list item 4: `prepare_audit_plan` (drilling.rs) marks
# trapped-and-unrescued cavity for refill in ONE relaxation pass
# (drilling.rs:1025-1040) -- it recomputes level-restricted drainability
# once, excluding whatever a component's own audit-rescue attempt failed to
# cover, and refills whatever still does not drain. `drill` then DEMANDS
# that this was already a fixpoint (drilling.rs:712-722): it recomputes
# drainability against the SAME final hole set and refill mask and requires
# the count to match exactly, else `DrillingRefusal::TrappedCavity`.
#
# Geometry, built to exercise exactly that machinery: a tall SPINE (16x16,
# Z0..90) carries the one planned drain near its base and is always fully
# drainable on its own (a single straight monotonic column, no dead end).
# Two chambers hang off its opposite faces through narrow, OFFSET necks --
# each neck bridges in from the SIDE, above the chamber's own floor, so each
# chamber has real depth below where its neck actually enters (the same
# "hangs from its own top" shape as fixture 2's short leg):
#
#   * CHAMBER-W (10x10x10, X14..24, Z56..66): its neck meets it only over
#     Z60..66, so its floor (Z56..60) is a dead end. At the 2.5mm wall its
#     cavity is roughly 5x5x7.5mm = ~188 mm^3 = ~0.19 mL -- comfortably
#     under HOLLOW_EXTRA_DRAIN_POLICY's min_pocket_ml (0.5 mL), so
#     `qualifies_audit_drain` refuses it on size alone: it is never even
#     offered a candidate ray, and step 3 refills it unconditionally.
#   * CHAMBER-MID (20x20x20, X-34..-14, Z30..50): its neck meets it only
#     over Z40..46, so ONLY its Z30..40 slice is a genuine dead end (the
#     Z40..50 slice above the neck already drains straight down through it
#     to the spine, no rescue needed). That Z30..40 slice's cavity is large
#     enough (~1.7 mL) and close enough to the exterior (walls are 2.5mm
#     everywhere) to both qualify by size and find a valid candidate
#     direction within HOLLOW_EXTRA_DRAIN_POLICY's exit_max_mm (8mm), so it
#     receives its own dedicated audit drain.
#
# This constructs precisely the two building blocks short-list item 4 names
# -- a component disqualified and refilled outright, and a SEPARATE
# component that is audit-rescued but only after the single relaxation pass
# has to work out which of its own voxels the new hole actually reaches --
# in one branched, multi-chamber cavity, which is the shape ("trunk plus
# limb plus limb") the review calls out as the concrete trigger shape.
#
# MEASURED, not assumed: this exact fixture, run through create_shell ->
# plan_drains -> drill_planned_shell with the registered M0 constants,
# drills successfully (no DrillingRefusal): 1 audit drain added, CHAMBER-W's
# 738 voxels (0.092 mL) refilled, and the drill()-side recount of drainable
# voxels equals prepare_audit_plan's own retained-voxel count exactly (both
# 100397). Tracing why: `drainability_map_admitted`'s single pass is a full
# union-find recompute over the WHOLE field for a FIXED exclusion set, not
# an incremental patch, so it already finds the complete set of voxels
# unreachable given that exclusion in one shot; excluding that whole set
# afterward cannot newly strand anything that had a genuinely independent
# path, because `has_drain` only ever propagates by OR into a shared root --
# a voxel already recorded as draining can never have been draining "through"
# a voxel later found not to drain, on pain of them sharing that root and
# therefore that same true/false value. This fixture is kept, and is
# genuinely useful, as a live regression test of that invariant (and of the
# audit-rescue-with-a-residual-dead-end path in general): it should keep
# drilling successfully after any change to this machinery. It is NOT
# (currently) a witness that reproduces short-list item 4's refusal outcome
# -- that would need either a genuinely different mechanism than the one
# reasoned about above, or a construction this file's author did not find.
# Report that gap rather than paper over it.
def make_cascade_pocket():
    spine = box(16, 16, 90, 0, 0, 45, "spine")
    neck_w = box(6, 10, 6, 11, 0, 63, "neck_w")              # X 8..14, Z 60..66
    chamber_w = box(10, 10, 10, 19, 0, 61, "chamber_w")      # X 14..24, Z 56..66
    neck_mid = box(6, 10, 6, -11, 0, 43, "neck_mid")         # X -14..-8, Z 40..46
    chamber_mid = box(20, 20, 20, -24, 0, 40, "chamber_mid")  # X -34..-14, Z 30..50
    union_onto(spine, [neck_w, chamber_w, neck_mid, chamber_mid])
    return spine


# ---------------------------------------------------------------------------
# FIXTURE 4 -- thin-fin.stl
#
# Targets short-list item 11: `NEAR_WALL_SKIP` (rust/geom_kernel/src/
# consts.rs:35, 0.05mm) discards any second ray crossing within 0.05mm of
# the first when `cone_thickness` (queries.rs:2930-2968) measures far-wall
# thickness for the support foot-ball breach predicate -- `breach_one`
# filters hits with `dd > nd + NEAR_WALL_SKIP`, so a genuine far wall
# thinner than that margin is invisible to the predicate, which reports the
# NEXT surface behind it (or no breach at all) instead. No witness geometry
# for this existed before this fixture (REVIEW.md: "needs a constructed
# geometry satisfying the surrounding precondition and was not built").
#
# Geometry: a 20mm cube BULK (identical to cube.stl's hollowing arithmetic:
# a 15mm cavity at the 2.5mm wall target, 3.375 mL saved, clears every
# hollow gate on its own) carries a FIN on its top face -- 10mm wide, 15mm
# tall, and 0.02mm thick in Y: exactly half of NEAR_WALL_SKIP, so a ray
# passing through it front-to-back has its far-side crossing well inside the
# skip margin of its near-side crossing and is a direct, deliberately
# minimal instance of the precondition the predicate is supposed to bound.
# The two boxes are joined (not booleaned) at their shared touching face --
# the same construction plinth_mesh's own `make_thin_fin_with` fixture uses
# for base+fin -- so each box's 12 edges stay independently manifold; no
# CSG is needed or wanted at 0.02mm.
#
# INTENDED CONSUMER, and a MEASURED limit: NEAR_WALL_SKIP is consumed by
# geom_kernel's own `NativeSurface`/`cone_thickness`/`breach_one` (exact
# triangle-mesh ray casting -- rust/geom_kernel/src/queries.rs), which this
# fixture's raw mesh and vertices feed directly; that is the intended use,
# and the bulk's own hollow-gate arithmetic above (identical to cube.stl,
# verified) establishes that the carrying shape is a genuine, practical
# hollowing target and not a contrived toy. It is NOT the intended use to
# push this fixture (bulk+fin as ONE mesh) through plinth-hollow's own
# create_shell -- measured directly: at the registered HOLLOW_PITCH_MM
# (0.5mm), the fin's 0.02mm thickness is 25x below one voxel, and
# create_shell's own surface-nets reconstruction of the carved cavity comes
# back with an extra spurious closed surface near the fin
# (`DrillingRefusal::SourceSurfaceCount { found: 3, expected: 2 }` when the
# drilled plan is pushed through drill_planned_shell). That is an honest,
# separate finding -- a sub-voxel-pitch feature breaking H0's own
# reconstruction, orthogonal to the near-wall-skip question this fixture
# targets -- not a defect in this fixture's geometry, and not something a
# smaller or larger sub-NEAR_WALL_SKIP thickness would avoid (anything
# satisfying "thinner than 0.05mm" is, by construction, sub-voxel at the
# registered 0.5mm pitch). Report it; do not paper over it by thickening
# the fin past the value short-list item 11 actually asks for.
def make_thin_fin():
    bulk = box(20, 20, 20, 0, 0, 10, "bulk")
    fin = box(10, 0.02, 15, 0, 0, 27.5, "fin")
    bpy.ops.object.select_all(action='DESELECT')
    bulk.select_set(True)
    fin.select_set(True)
    bpy.context.view_layer.objects.active = bulk
    bpy.ops.object.join()
    return bulk


FIXTURES = {
    "legs-uneven": make_legs_uneven,
    "cascade-pocket": make_cascade_pocket,
    "thin-fin": make_thin_fin,
}


def main():
    argv = sys.argv[sys.argv.index("--") + 1:]
    if len(argv) != 2 or argv[0] not in FIXTURES:
        sys.stderr.write(
            f"usage: blender --background --factory-startup --python generate.py "
            f"-- <{'|'.join(FIXTURES)}> <output.stl>\n"
        )
        sys.exit(1)
    name, out_path = argv
    bpy.ops.wm.read_factory_settings(use_empty=True)
    obj = FIXTURES[name]()
    export(obj, out_path)


if __name__ == "__main__":
    main()
